      visitors.filter(person=>person.gender==='女'&&isFertileAge(person)&&person.spouseId&&!person.pregnancy&&person.satisfaction>=100).forEach(wife=>{const husband=residentById(wife.spouseId),home=sharedPrivateHome(wife,husband);if(!isFertileAge(husband)||husband.satisfaction<100||!garden.workerIds.includes(husband.id))return;if(!home||home.residents.length>=housingCapacity(home))return;if(state.people.length+activePregnancies()>=bedCapacity())return;wife.pregnancy={fatherId:husband.id,dueAt:now+PREGNANCY_MS,deliveryWarned:false,laborWarned:false};changed=true;toast(`${wife.name} 怀孕了，预计 9 天后生产`);celebrate(state.people.map(person=>person.id),'新生命即将到来！')});
