  function createChild(mother,father){const gender=Math.random()<.5?'男':'女',parentSurnames=[father?.surname||father?.name?.slice(0,1),mother?.surname||mother?.name?.slice(0,1)].filter(Boolean),surname=random(parentSurnames.length?parentSurnames:SURNAMES),used=state.people.map(person=>person.name),now=Date.now(),name=randomName(gender,used,surname),sprites=gender==='男'?[0,2,4,6]:[1,3,5,7],currentSlot=mealSlotAt(now,state.createdAt),currentMilkSlot=milkSlotAt(now,state.createdAt);return{id:`p-${now}-${state.people.length}`,name,surname,gender,age:0,education:'无',talent:'无',money:0,satisfaction:60,satiety:100,satietyZeroSince:null,deathPending:false,foodPreference:'auto',milkPreference:'auto',lastMealSlot:currentSlot,lastMilkSlot:currentMilkSlot,spouseId:null,pregnancy:null,sick:false,sickCause:null,sickUntil:null,clinicFloorId:null,parentIds:[father?.id,mother.id].filter(Boolean),skills:Object.fromEntries(SKILLS.map(skill=>[skill,0])),sprite:random(sprites)}}
